const entrada = $json.body ?? $json;

function obj(v) { return v && typeof v === 'object' && !Array.isArray(v) ? v : {}; }
function get(o, path) { return path.split('.').reduce((v, k) => obj(v)[k], o); }
function primeiro(paths) {
  for (const path of paths) {
    const value = get(entrada, path);
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number') return String(value);
  }
  return null;
}
function achar(value, teste, depth = 0) {
  if (depth > 8 || value == null) return null;
  if (typeof value === 'string' && teste(value)) return value;
  if (Array.isArray(value)) {
    for (const item of value) { const achado = achar(item, teste, depth + 1); if (achado) return achado; }
    return null;
  }
  if (typeof value === 'object') {
    for (const item of Object.values(value)) { const achado = achar(item, teste, depth + 1); if (achado) return achado; }
  }
  return null;
}

let chatId = primeiro(['chatid','chatId','ChatID','chat.wa_chatid','key.remoteJid','message.key.remoteJid','Data.Key.remoteJid','Data.Key.RemoteJid','Data.Info.Chat','Data.Info.MessageSource.Chat']);
chatId = chatId ?? achar(entrada, v => /\d[\d-]{5,}@g\.us/i.test(v));
if (chatId && !/@g\.us$/i.test(chatId) && /^(120363\d{8,}|\d{8,}-\d{5,})$/.test(chatId)) chatId += '@g.us';

const text = primeiro(['text','content','caption','message.text','message.content','message.caption','Data.Message.conversation','Data.Message.extendedTextMessage.text','Data.Message.imageMessage.caption','Data.Message.videoMessage.caption']);
const sender = primeiro(['sender','senderJid','participant','key.participant','message.key.participant','Data.Key.participant','Data.Info.Sender','from']);
const senderPhone = primeiro(['sender_pn','senderPhone','phone','number']);
const senderName = primeiro(['senderName','pushName','notifyName','Data.PushName','Data.Info.PushName']);
const groupName = primeiro(['chatName','chat.name','chat.wa_name','groupName','group_name']);
const externalId = primeiro(['messageid','messageId','message.id','key.id','Data.Key.id','Data.Key.ID']);

if (!chatId) throw new Error('Não encontrei o ID do grupo no webhook da UAZAPI');

return [{ json: {
  chatid: chatId,
  text,
  sender,
  senderPhone,
  senderName,
  groupName,
  messageId: externalId,
  rawPayload: entrada
} }];
